def mock_validate_int_btwn(value, min, max):
    """
    Copied from the in-use validator so we can test values here.
    """
    if int(value) < min or int(value) > max:
        raise ValidationError(
            ("Please enter a number between %(min)s and %(max)s. The number %(value)s is not valid."),
            params={
                "value": value,
                "min": min,
                "max": max
            },
        )


def populate_flat_drawing_locations(apps, schema_editor):
    """
    Creates new dedicated locationset objects for any FlatDrawings (fd's) with at least one full set of locations
    """
    FlatDrawing = apps.get_model("docsearch", "FlatDrawing")
    LocationSet = apps.get_model("docsearch", "LocationSet")

    # Only migrate locations if FlatDrawing has at least one full set
    has_locations_filter = (
        Q(section__isnull=False, area__isnull=False)
        | Q(cross_ref_section__isnull=False, cross_ref_area__isnull=False)
    )
    fds_with_locations = (
        FlatDrawing.objects
        .filter(has_locations_filter)
    )

    location_sets_to_create = []
    for fd in fds_with_locations:
        # One flat drawing can have both primary and secondary locations
        location_values = [
            (fd.section,fd.area),
            (fd.cross_ref_section,fd.cross_ref_area)
        ]

        for i, section_area_pair in enumerate(location_values):
            if not all(section_area_pair):
                continue

            # Only migrate locations if both values are *valid*
            try:
                section, area = section_area_pair
                mock_validate_int_btwn(section, 1, 36)
                mock_validate_int_btwn(area, 1, 33)
            except ValidationError as e:
                locations_label = "primary set" if i == 0 else "secondary set"
                logger.error(f"Error on FlatDrawing ID={fd.id} : {e}")
                logger.error(f"Skipping LocationSet creation for this FD's {locations_label}...")
                logger.info("======")
            else:
                location_sets_to_create.append(
                    LocationSet(
                        flat_drawing=fd,
                        section=section_area_pair[0],
                        area=section_area_pair[1]
                    )
                )

    LocationSet.objects.bulk_create(location_sets_to_create)
    logger.info(f"FlatDrawings touched: {len(fds_with_locations)}")
    logger.info(f"LocationSet objects created: {len(location_sets_to_create)}")


